-- 07_retrip_crawl_yeongdeungpo.sql — 영등포구 네이버 크롤링 (11/06~07 ① 이상재, 크롤러 retrip_crawl.py build 결과를 그대로 합친 파일). 06 다음, 08 전에 실행
--  새 테이블 4개(place_hours 요일별 영업시간, place_menu 메뉴, place_keyword 방문자 키워드 통계, place_image 사진 여러 장)
--  + retrip_place 새 칸 5개(way_text, place_group, biz_status, status_checked_at, last_review_date)
--  + 영등포 기존 네이버 가게 444곳 갱신(영업시간·평점·리뷰 수·전화·편의시설·찾아가는 길·사진·리뷰 10개) + 새 가게 917곳(음식점·카페·술집)
--  이 파일 안에 BEGIN·COMMIT이 두 번 있어요 (앞 절반 = 기존 가게, 뒤 절반 = 새 가게). 다시 실행해도 같은 결과
--  꼭 08 → 09 → 10을 이 뒤에 다시 실행: 폐업·중복 삭제, 편의시설 표준 이름, 시연 장소 값, 날짜 붙은 휴무 정리가 이 파일 위에 다시 적용돼요
--  실행: "C:\Program Files\PostgreSQL\17\bin\psql.exe" -h localhost -p 5432 -U postgres -d tripbiseo -f db\07_retrip_crawl_yeongdeungpo.sql
-- ===== 1/2 기존 가게 갱신 + 새 테이블 =====
-- 여행어때: 영업시간 상세(브레이크·라스트오더)·메뉴·키워드 리뷰 테이블 + 기존 네이버 가게 444곳 갱신
-- retrip_crawl.py refresh 결과로 만듦 (2026-11-07T07:37:03.000Z). 04 다음에 실행. 여러 번 실행해도 안전.
\encoding UTF8

BEGIN;

CREATE TABLE IF NOT EXISTS place_hours (
  place_id    TEXT REFERENCES retrip_place(id) ON DELETE CASCADE,
  weekday     SMALLINT NOT NULL,   -- 0=월 … 6=일
  open_min    INT,                 -- 자정부터 분. 새벽 2시 마감이면 close_min = 1560
  close_min   INT,
  break_start INT,
  break_end   INT,
  last_order  INT,
  closed      BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (place_id, weekday)
);

CREATE TABLE IF NOT EXISTS place_menu (
  place_id TEXT REFERENCES retrip_place(id) ON DELETE CASCADE,
  seq INT, name TEXT NOT NULL, price INT, is_main BOOLEAN DEFAULT FALSE,
  PRIMARY KEY (place_id, seq)
);

CREATE TABLE IF NOT EXISTS place_keyword (
  place_id TEXT REFERENCES retrip_place(id) ON DELETE CASCADE,
  keyword TEXT NOT NULL, cnt INT NOT NULL,
  PRIMARY KEY (place_id, keyword)
);

ALTER TABLE retrip_place ADD COLUMN IF NOT EXISTS way_text TEXT;
ALTER TABLE retrip_place ADD COLUMN IF NOT EXISTS place_group TEXT;   -- 분류: 음식점·카페·술집·편의점·쇼핑·체험·놀거리·생활편의·숙박·관광·문화·기타
CREATE INDEX IF NOT EXISTS idx_retrip_place_group ON retrip_place (place_group);

-- 사진 주소(가게당 여러 장). 대표 사진은 retrip_place.image_url
CREATE TABLE IF NOT EXISTS place_image (
  place_id TEXT REFERENCES retrip_place(id) ON DELETE CASCADE,
  seq INT, url TEXT NOT NULL,
  PRIMARY KEY (place_id, seq)
);

-- 영업 상태 확인(갱신용): 영업 / 폐업 / 휴업 / 이전 / 확인 필요(네이버에서 가게가 사라짐)
ALTER TABLE retrip_place ADD COLUMN IF NOT EXISTS biz_status TEXT;
ALTER TABLE retrip_place ADD COLUMN IF NOT EXISTS status_checked_at TEXT;
ALTER TABLE retrip_place ADD COLUMN IF NOT EXISTS last_review_date TEXT;   -- 가장 최근 방문자 리뷰 날짜(오래 끊기면 폐업 의심)

